/** Failure raised anywhere in the expression pipeline. */
export class ExprError extends Error {
  /**
   * @param {string} message reason, ending with the position it refers to
   * @param {number} index 0-based index into the source, in UTF-16 code units
   */
  constructor(message, index) {
    super(`${message} at ${index}`);
    this.name = 'ExprError';
    this.index = index;
  }
}

const NUMBER_RE = /^(\d+(\.\d+)?|\.\d+)([eE][+-]?\d+)?$/;
const NAME_START_RE = /[A-Za-z_]/;
const NAME_CONT_RE = /[A-Za-z0-9_]/;
const OPERATOR_CHARS = new Set(['+', '-', '*', '/', '%', '^']);

/**
 * Split an expression into tokens.
 *
 * @param {string} input expression source
 * @returns {{ type: 'number' | 'name' | 'operator' | 'lparen' | 'rparen' | 'comma', value: number | string, index: number }[]}
 *   tokens in source order
 */
export function tokenize(input) {
  const tokens = [];
  const length = input.length;
  let i = 0;

  while (i < length) {
    const ch = input[i];

    if (/\s/.test(ch)) {
      i += 1;
      continue;
    }

    if (/\d/.test(ch) || (ch === '.' && /\d/.test(input[i + 1] ?? ''))) {
      const start = i;
      let j = i;
      while (j < length) {
        const c = input[j];
        if (/[0-9a-zA-Z_.]/.test(c)) {
          j += 1;
          continue;
        }
        if ((c === '+' || c === '-') && j > start && /[eE]/.test(input[j - 1])) {
          j += 1;
          continue;
        }
        break;
      }
      const raw = input.slice(start, j);
      if (!NUMBER_RE.test(raw)) {
        throw new ExprError('malformed number', start);
      }
      tokens.push({ type: 'number', value: Number(raw), index: start });
      i = j;
      continue;
    }

    if (NAME_START_RE.test(ch)) {
      const start = i;
      let j = i + 1;
      while (j < length && NAME_CONT_RE.test(input[j])) j += 1;
      tokens.push({ type: 'name', value: input.slice(start, j), index: start });
      i = j;
      continue;
    }

    if (OPERATOR_CHARS.has(ch)) {
      tokens.push({ type: 'operator', value: ch, index: i });
      i += 1;
      continue;
    }

    if (ch === '(') {
      tokens.push({ type: 'lparen', value: ch, index: i });
      i += 1;
      continue;
    }

    if (ch === ')') {
      tokens.push({ type: 'rparen', value: ch, index: i });
      i += 1;
      continue;
    }

    if (ch === ',') {
      tokens.push({ type: 'comma', value: ch, index: i });
      i += 1;
      continue;
    }

    const codePoint = input.codePointAt(i);
    const text = String.fromCodePoint(codePoint);
    throw new ExprError(`unexpected character '${text}'`, i);
  }

  return tokens;
}
"}

