{"file_path":"src/parse.js","content":"/** Precedence-climbing parser producing the expression tree. */

import { ExprError, tokenize } from './tokenize.js';

const BINARY_PRECEDENCE = { '+': 1, '-': 1, '*': 2, '/': 2, '%': 2, '^': 4 };

function tokenText(token) {
  if (token.type === 'number') return String(token.value);
  return String(token.value);
}

/**
 * Parse an expression into a tree.
 *
 * @param {string} input expression source
 * @returns {object} the expression tree; parentheses leave no node behind
 */
export function parse(input) {
  const tokens = tokenize(input);
  const length = input.length;
  let pos = 0;

  function peek() {
    return tokens[pos];
  }

  function endIndex() {
    return length;
  }

  function expectMore() {
    if (pos >= tokens.length) {
      throw new ExprError('unexpected end of input', endIndex());
    }
    return tokens[pos];
  }

  function parseExpression(minPrecedence) {
    let left = parseUnary();
    for (;;) {
      const token = peek();
      if (!token || token.type !== 'operator') break;
      const precedence = BINARY_PRECEDENCE[token.value];
      if (precedence < minPrecedence) break;
      pos += 1;
      const rightAssociative = token.value === '^';
      const nextMin = rightAssociative ? precedence : precedence + 1;
      const right = parseExpression(nextMin);
      left = { type: 'binary', op: token.value, left, right, index: token.index };
    }
    return left;
  }

  function parseUnary() {
    const token = expectMore();
    if (token.type === 'operator' && (token.value === '+' || token.value === '-')) {
      pos += 1;
      const operand = parseUnary();
      return { type: 'unary', op: token.value, operand, index: token.index };
    }
    return parsePrimary();
  }

  function parsePrimary() {
    const token = expectMore();

    if (token.type === 'number') {
      pos += 1;
      return { type: 'number', value: token.value, index: token.index };
    }

    if (token.type === 'name') {
      pos += 1;
      const next = peek();
      if (next && next.type === 'lparen') {
        pos += 1;
        const args = [];
        const closeCheck = peek();
        if (closeCheck && closeCheck.type === 'rparen') {
          pos += 1;
        } else {
          for (;;) {
            args.push(parseExpression(0));
            const after = expectMore();
            if (after.type === 'comma') {
              pos += 1;
              continue;
            }
            if (after.type === 'rparen') {
              pos += 1;
              break;
            }
            throw new ExprError(`unexpected token '${tokenText(after)}'`, after.index);
          }
        }
        return { type: 'call', name: token.value, args, index: token.index };
      }
      return { type: 'variable', name: token.value, index: token.index };
    }

    if (token.type === 'lparen') {
      pos += 1;
      const inner = parseExpression(0);
      const closeToken = tokens[pos];
      if (!closeToken || closeToken.type !== 'rparen') {
        const missingIndex = closeToken ? closeToken.index : endIndex();
        throw new ExprError('missing closing parenthesis', missingIndex);
      }
      pos += 1;
      return inner;
    }

    throw new ExprError(`unexpected token '${tokenText(token)}'`, token.index);
  }

  const tree = parseExpression(0);
  if (pos < tokens.length) {
    const token = tokens[pos];
    throw new ExprError(`unexpected token '${tokenText(token)}'`, token.index);
  }
  return tree;
}
"}

